const envelope = $json.body || $json;
const allowed = new Set(['lead.qualified','lead.followup.requested','lead.followup.scheduled','lead.handoff.requested','booking.created','booking.confirmed','booking.completed','booking.no-show','booking.rescheduled','booking.cancelled']);
if (!envelope.event || !allowed.has(envelope.event)) {
  throw new Error('Unsupported or missing TataEV event');
}
if (!envelope.eventId || !envelope.data) {
  throw new Error('Invalid TataEV event envelope');
}
return [{ json: { ...envelope, accepted: true, route: envelope.event.split('.')[0] } }];
